// Auto-generated by AI Terminal Tools
// Sends OpenCode turn/file events to the IDEA plugin.
// Runtime config is read from the current OpenCode process environment.

function env(name) {
  if (typeof process !== "undefined" && process && process.env && process.env[name]) return process.env[name]
  if (typeof Bun !== "undefined" && Bun && Bun.env) return Bun.env[name] || ""
  return ""
}

function config() {
  return {
    port: env("AITT_PORT"),
    token: env("AITT_TOKEN"),
    tabId: env("AITT_TAB_ID")
  }
}

async function post(type, extra) {
  var cfg = config()
  if (!cfg.port || !cfg.token || !cfg.tabId) return
  if (!extra) extra = {}
  extra.source = "opencode"
  extra.type = type
  extra.tabId = cfg.tabId
  try {
    await fetch("http://127.0.0.1:" + cfg.port + "/event", {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-aitt-token": cfg.token
      },
      body: JSON.stringify(extra)
    })
  } catch (_) {}
}

function sessionID(ev) {
  return (ev && ev.properties && (ev.properties.sessionID || ev.properties.sessionId)) ||
    (ev && (ev.sessionID || ev.sessionId)) || ""
}

function extractPaths(obj, result) {
  if (!result) result = []
  if (!obj || typeof obj !== "object") return result
  for (var key in obj) {
    var val = obj[key]
    if (typeof val === "string" && val.length > 0) {
      var kl = key.toLowerCase()
      if (kl === "file" || kl === "path" || kl === "filepath" ||
          kl === "file_path" || kl === "filename" || kl === "file_name") {
        if (val.length < 500 && val.indexOf("\n") < 0 &&
            val.indexOf("{") !== 0 && val.indexOf("[") !== 0) {
          result.push(val)
        }
      }
    } else if (Array.isArray(val)) {
      for (var i = 0; i < val.length; i++) extractPaths(val[i], result)
    } else if (typeof val === "object" && val !== null) {
      extractPaths(val, result)
    }
  }
  return result
}

function extractPatchPaths(patchText) {
  var result = []
  if (typeof patchText !== "string" || patchText.length === 0) return result
  var lines = patchText.split(/\r?\n/)
  for (var i = 0; i < lines.length; i++) {
    var fileMatch = lines[i].match(/^\*\*\* (?:Add|Update|Delete) File: (.+)$/)
    var moveMatch = lines[i].match(/^\*\*\* Move to: (.+)$/)
    var path = fileMatch ? fileMatch[1] : (moveMatch ? moveMatch[1] : "")
    if (path) result.push(path)
  }
  return result
}

function isWriteTool(input) {
  var tool = input && input.tool
  return tool === "edit" || tool === "write" || tool === "apply_patch"
}

function extractWriteToolPaths(input, output) {
  var tool = input && input.tool
  if (tool === "apply_patch") {
    var patchArgs = (output && output.args) || (input && input.args) || {}
    return unique(extractPatchPaths(patchArgs.patchText))
  }
  return unique(
    extractPaths(output && output.args)
      .concat(extractPaths(input && input.args))
  )
}

function unique(arr) {
  var seen = {}
  var out = []
  for (var i = 0; i < arr.length; i++) {
    if (!seen[arr[i]]) { seen[arr[i]] = true; out.push(arr[i]) }
  }
  return out
}

export var AiTerminalTools = async function() {
  return {
    event: async function(ctx) {
      var ev = ctx.event
      if (!ev) return

      if (ev.type === "session.status") {
        var status = ev.properties && ev.properties.status
        if (status && status.type === "busy") {
          await post("turn_start", { sessionID: sessionID(ev) })
        }
        return
      }

      if (ev.type === "session.idle") {
        await post("turn_end", { sessionID: sessionID(ev) })
        return
      }

      if (ev.type === "file.edited") {
        var file = ev.properties && ev.properties.file
        if (file) await post("file_changed", { paths: [file], sessionID: sessionID(ev) })
      }
    },

    "tool.execute.before": async function(input, output) {
      if (!isWriteTool(input)) return
      var paths = extractWriteToolPaths(input, output)
      if (paths.length > 0) {
        await post("before_write", { paths: paths, sessionID: input && input.sessionID })
      }
    },

    "tool.execute.after": async function(input, output) {
      if (!isWriteTool(input)) return
      var paths = extractWriteToolPaths(input, output)
      if (paths.length > 0) {
        await post("file_changed", { paths: paths, sessionID: input && input.sessionID })
      }
    }
  }
}
